('w4', 4, 6, 'descomposicion_prima', '¡Reto Minero! Descompón el número 36 en puros factores primos.', '["2 x 2 x 3 x 3", "6 x 6", "4 x 9", "2 x 2 x 9"]', 0, '36 / 2 = 18. Luego 18 / 2 = 9. Luego 9 / 3 = 3. Y 3 / 3 = 1. Los factores son 2 x 2 x 3 x 3.'),
('w4', 4, 7, 'descomposicion_prima', '¡Reto Minero! Descompón el número 36 en puros factores primos.', '["2 x 2 x 9", "2 x 2 x 3 x 3", "4 x 9", "6 x 6"]', 1, '36 / 2 = 18. Luego 18 / 2 = 9. Luego 9 / 3 = 3. Y 3 / 3 = 1. Los factores son 2 x 2 x 3 x 3.'),
('w4', 4, 8, 'descomposicion_prima', '¡Desafío! Encuentra la descomposición correcta para el número 20:', '["2 x 10", "2 x 2 x 5", "2 x 3 x 3", "4 x 5"]', 1, 'Recuerda que TODOS los números deben ser primos. "4 x 5" da 20, pero el 4 no es primo. La correcta es 2 x 2 x 5.'),
('w4', 4, 9, 'descomposicion_prima', '¡Desafío! ¡Reto Minero! Descompón el número 36 en puros factores primos.', '["2 x 2 x 9", "2 x 2 x 3 x 3", "6 x 6", "4 x 9"]', 1, '36 / 2 = 18. Luego 18 / 2 = 9. Luego 9 / 3 = 3. Y 3 / 3 = 1. Los factores son 2 x 2 x 3 x 3.'),
